// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.animation.core.LinearEasingimport androidx.compose.animation.core.RepeatModeimport androidx.compose.animation.core.animateFloatimport androidx.compose.animation.core.infiniteRepeatableimport androidx.compose.animation.core.rememberInfiniteTransitionimport androidx.compose.animation.core.tweenimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.borderimport androidx.compose.foundation.clickableimport androidx.compose.foundation.interaction.MutableInteractionSourceimport androidx.compose.foundation.interaction.collectIsPressedAsStateimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.AutoAwesomeimport androidx.compose.material.icons.filled.Homeimport androidx.compose.material.icons.filled.Micimport androidx.compose.material.icons.filled.PhotoCameraimport androidx.compose.material.icons.filled.Settingsimport androidx.compose.material.icons.outlined.AutoAwesomeimport androidx.compose.material.icons.outlined.Homeimport androidx.compose.material.icons.outlined.PhotoCameraimport androidx.compose.material.icons.outlined.Settingsimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.rememberimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.scaleimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.theme.LocalAuroraBrush/** * Bottom navigation — 5 tabs with elevated center mic FAB. * * @param activeTab current selected tab * @param onTabSelected callback when tab changes * @param onMicClick callback when center mic button is tapped * @param isListening when true, mic button pulses red */@Composablefun NousBottomNav(    activeTab: NavTab,    onTabSelected: (NavTab) -> Unit,    onMicClick: () -> Unit,    isListening: Boolean,    modifier: Modifier = Modifier,) {    Row(        modifier = modifier            .fillMaxWidth()            .background(color = MaterialTheme.colorScheme.surface.copy(alpha = 0.95f))            .padding(horizontal = 16.dp, vertical = 12.dp),        horizontalArrangement = Arrangement.SpaceBetween,        verticalAlignment = Alignment.CenterVertically,    ) {        NavTabButton(            tab = NavTab.Home,            active = activeTab == NavTab.Home,            onSelected = { onTabSelected(NavTab.Home) },        )        NavTabButton(            tab = NavTab.Vision,            active = activeTab == NavTab.Vision,            onSelected = { onTabSelected(NavTab.Vision) },        )        MicFab(onClick = onMicClick, isListening = isListening)        NavTabButton(            tab = NavTab.Skills,            active = activeTab == NavTab.Skills,            onSelected = { onTabSelected(NavTab.Skills) },        )        NavTabButton(            tab = NavTab.Settings,            active = activeTab == NavTab.Settings,            onSelected = { onTabSelected(NavTab.Settings) },        )    }}enum class NavTab(val label: String, val icon: ImageVector, val activeIcon: ImageVector) {    Home("Home", Icons.Outlined.Home, Icons.Filled.Home),    Vision("Vision", Icons.Outlined.PhotoCamera, Icons.Filled.PhotoCamera),    Skills("Skills", Icons.Outlined.AutoAwesome, Icons.Filled.AutoAwesome),    Settings("Settings", Icons.Outlined.Settings, Icons.Filled.Settings),}@Composableprivate fun NavTabButton(    tab: NavTab,    active: Boolean,    onSelected: () -> Unit,) {    val interactionSource = remember { MutableInteractionSource() }    val isPressed by interactionSource.collectIsPressedAsState()    val scale = if (isPressed) 0.94f else 1f    val icon = if (active) tab.activeIcon else tab.icon    val tint = if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant    Column(        modifier = Modifier            .scale(scale)            .clickable(                interactionSource = interactionSource,                indication = null,                onClick = onSelected,            )            .padding(horizontal = 12.dp, vertical = 4.dp),        horizontalAlignment = Alignment.CenterHorizontally,    ) {        Icon(            imageVector = icon,            contentDescription = tab.label,            tint = tint,            modifier = Modifier.size(22.dp),        )        Spacer(modifier = Modifier.size(2.dp))        Text(            text = tab.label,            style = MaterialTheme.typography.labelSmall,            color = tint,        )    }}@Composableprivate fun MicFab(    onClick: () -> Unit,    isListening: Boolean,) {    val interactionSource = remember { MutableInteractionSource() }    val isPressed by interactionSource.collectIsPressedAsState()    val scale = if (isPressed) 0.92f else 1f    val infinite = rememberInfiniteTransition(label = "mic_pulse")    val pulseScale by infinite.animateFloat(        initialValue = 1f,        targetValue = if (isListening) 1.3f else 1.05f,        animationSpec = infiniteRepeatable(            animation = tween(1500, easing = LinearEasing),            repeatMode = RepeatMode.Reverse,        ),        label = "mic_pulse_scale",    )    val brush = LocalAuroraBrush.current    val micColor = if (isListening) Color(0xFFF43F5E) else Color.White    val backgroundModifier: Modifier = if (isListening) {        Modifier.background(color = Color(0xFFF43F5E), shape = CircleShape)    } else {        Modifier.background(brush = brush, shape = CircleShape)    }    Box(        modifier = Modifier            .size(64.dp)            .scale(scale * pulseScale)            .then(backgroundModifier)            .border(                width = 2.dp,                color = if (isListening) Color(0xFFF43F5E).copy(alpha = 0.4f) else Color.Transparent,                shape = CircleShape,            )            .clickable(                interactionSource = interactionSource,                indication = null,                onClick = onClick,            ),        contentAlignment = Alignment.Center,    ) {        Icon(            imageVector = Icons.Filled.Mic,            contentDescription = "Voice input",            tint = micColor,            modifier = Modifier.size(28.dp),        )    }}